// hud-manager/tests/unit.mjs
//
// Юнит-тесты чистой логики: разбор HUD, коды, имена, утилиты, маска
// рассуждений. Без браузера и без модели: node tests/unit.mjs
// Код выхода 1, если хоть одна проверка провалилась.

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const КОРЕНЬ = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ВЕРСИЯ = JSON.parse(fs.readFileSync(path.join(КОРЕНЬ, 'manifest.json'), 'utf8')).version;

// Минимальное окружение браузера: модули читают window, localStorage и
// document.createElement (escapeHtml экранирует через textContent).
globalThis.window = globalThis;
globalThis.localStorage = { getItem: () => null, setItem() {}, removeItem() {} };
globalThis.sessionStorage = { getItem: () => null, setItem() {}, removeItem() {} };
const узел = () => {
  let t = '';
  return {
    style: {}, dataset: {}, classList: { add() {}, remove() {}, toggle() {} },
    set textContent(x) { t = String(x); },
    get innerHTML() { return t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); },
    querySelector: () => null, querySelectorAll: () => [],
  };
};
globalThis.document = { createElement: узел, querySelector: () => null, querySelectorAll: () => [], documentElement: узел() };
globalThis.SillyTavern = { getContext: () => ({ chat: [], name1: 'Софи', name2: 'Тристан' }) };
for (const k of ['info', 'debug', 'warn']) console[k] = () => {};

// Та же строка версии, что у внутренних импортов: иначе модули загрузились
// бы дважды, и общий объект настроек разошёлся бы на две копии.
const модуль = (имя) => import('file:///' + path.join(КОРЕНЬ, имя).replace(/\\/g, '/') + '?v=' + ВЕРСИЯ);
const P = await модуль('hud-parser.js');
const C = await модуль('codes.js');
const N = await модуль('names.js');
const U = await модуль('utils.js');
const B = await модуль('hud-block.js');
const Sch = await модуль('schema.js');

let всего = 0;
const провалы = [];
let раздел = '';
function группа(имя) { раздел = имя; console.log('\n— ' + имя); }
function проверить(что, ок, подробности = '') {
  всего++;
  if (ок) { console.log('  ✓ ' + что); return; }
  провалы.push(раздел + ': ' + что);
  console.log('  ✗ ' + что + (подробности !== '' ? '\n      ' + String(подробности).slice(0, 400) : ''));
}
const равно = (что, было, ждали) => проверить(что, JSON.stringify(было) === JSON.stringify(ждали), `вышло ${JSON.stringify(было)}, ждали ${JSON.stringify(ждали)}`);
const бросает = (f) => { try { f(); return false; } catch (_) { return true; } };

const hud = (obj) => '[HUD]\n```json\n' + JSON.stringify(obj) + '\n```\n[/HUD]';

// ---------------------------------------------------------------------------
группа('hud-parser: разбор блока');
{
  const д = P.parseHUDComplex(hud({ sc: { T: '21:40', Wt: 'дождь', Dt: '17.10.2024' }, cs: [{ N: 'Лилиан', A: '24', L: 'кофейня' }] }));
  равно('сцена: коды развёрнуты в русские поля', [д.scene['Время'], д.scene['Погода'], д.scene['Дата']], ['21:40', 'дождь', '17.10.2024']);
  равно('персонаж: имя, возраст, место', [д.characters[0]['Имя'], д.characters[0]['Возраст'], д.characters[0]['Место']], ['Лилиан', '24', 'кофейня']);

  const голый = P.parseHUDComplex('[HUD]{"sc":{"T":"09:00"},"cs":[{"N":"Марк"}]}[/HUD]');
  равно('json без ограды ```', голый.characters[0]['Имя'], 'Марк');

  const внутри = P.parseHUDComplex(JSON.stringify({ sc: { T: '10:00' }, cs: [{ N: 'Анна' }] }));
  равно('голый json без тегов', внутри.characters[0]['Имя'], 'Анна');

  const запятая = P.parseHUDComplex('[HUD]\n```json\n{"sc":{"T":"11:00",},"cs":[{"N":"Олег",},],}\n```\n[/HUD]');
  равно('висячие запятые чинятся', запятая.characters[0]['Имя'], 'Олег');

  const кавычки = P.parseHUDComplex('[HUD]\n```json\n{"sc":{"T":"12:00"},"cs":[{"N":"Ева","Th":"Он сказал «уходи»"}]}\n```\n[/HUD]');
  равно('«ёлочки» внутри значения', кавычки.characters[0]['Мысли'], 'Он сказал «уходи»');

  const подсветка = '[HUD]<pre><code class="language-json">{<span class="hljs-attr">"sc"</span>: {"T": "13:00"}, "cs": [{"N": "Ида"}]}</code></pre>[/HUD]';
  равно('HTML-подсветка кода снимается', P.parseHUDComplex(подсветка).characters[0]['Имя'], 'Ида');

  const два = P.parseHUDComplex('Служебное: {"debug": true}\n' + hud({ sc: { T: '14:00' }, cs: [{ N: 'Вера' }] }));
  равно('из двух JSON берётся похожий на HUD', два.characters[0]['Имя'], 'Вера');

  проверить('мусор без JSON — ошибка, а не пустой HUD', бросает(() => P.parseHUDComplex('[HUD]просто текст[/HUD]')));

  const стиль = P.parseHUDComplex('[HUD]<style>.x{color:red}</style>' + JSON.stringify({ sc: { T: '15:00' }, cs: [{ N: 'Зоя' }] }) + '[/HUD]');
  равно('<style> в блоке не мешает', стиль.characters[0]['Имя'], 'Зоя');

  const сырой = P.разобратьHUDСырой(hud({ sc: { T: '16:00' }, cs: [{ N: 'Лев', Th: 'пора' }] }));
  равно('сырой разбор сохраняет короткие коды', Object.keys(сырой.cs[0]).sort(), ['N', 'Th']);
}

// ---------------------------------------------------------------------------
группа('hud-parser: YAML и оценка');
{
  const y = P.parseSimpleYaml('sc:\n  T: "17:00"\ncs:\n  - N: Кира\n    L: парк');
  проверить('простой YAML разбирается', y && y.sc && y.sc.T === '17:00' && Array.isArray(y.cs) && y.cs[0].N === 'Кира', JSON.stringify(y));
  проверить('HUD-похожий объект оценивается выше служебного', P.scoreHudJsonCandidate({ sc: {}, cs: [{ N: 'a' }] }) > P.scoreHudJsonCandidate({ debug: true }));
}

// ---------------------------------------------------------------------------
группа('codes: слова-перечисления');
{
  равно('прогноз: период и погода', C.строкаПрогноза('morning | clear | +7°C | туман'), 'Утро | ясно | +7°C | туман');
  равно('прогноз: старые короткие коды', C.строкаПрогноза('mo | rn | +5°C'), 'Утро | дождь | +5°C');
  равно('гороскоп: знак и тон', C.строкаГороскопа('aries | смелость | lucky'), 'Овен | смелость | удача');
  равно('маршрут: последнее слово', C.строкаМаршрута('19:30 - Кофе-хаус - arrived'), '19:30 - Кофе-хаус - прибытие');
  равно('маршрут: дефис в названии не трогаем', C.строкаМаршрута('12:00 - Санкт-Петербург'), '12:00 - Санкт-Петербург');
  равно('сообщение: код статуса', C.строкаСообщения('А -> Б: привет | 10:00 | ur'), 'А -> Б: привет | 10:00 | Unread');
  равно('сообщение: исход звонка', C.строкаСообщения('А -> Б: [CALL: in, mi] | 10:00'), 'А -> Б: [CALL: in, missed] | 10:00');
  равно('стадия болезни по слову', C.стадияБолезни('healing').ключ, 'healing');
  равно('стадия болезни по-русски', C.стадияБолезни('заживает').ключ, 'healing');
  равно('ружьё: статус', C.статусРужья('fired').текст, 'выстрелило');
  равно('ружьё: неизвестное — висит', C.статусРужья('что-то').ключ, 'open');
  равно('сила страха', C.силаСтраха('panic'), 'до паники');
  равно('фаза близости', C.фазаБлизости('ag'), 'afterglow');
  равно('незнакомое слово остаётся как есть', C.силаСтраха('странно'), 'странно');
}

// ---------------------------------------------------------------------------
группа('codes: развернуть и свернуть');
{
  const к = { sc: { T: '10:00', Wt: 'ясно' }, cs: [{ N: 'Лилиан', Th: 'пора' }], me: { lg: ['10:00 - кофе'], sec: [{ f: 'тайна', lv: 'high' }] }, phn: { ow: 'Лилиан', ct: [{ n: 'Марк' }] } };
  const р = C.развернутьКоды(JSON.parse(JSON.stringify(к)));
  проверить('корень развёрнут', р.scene && р.characters && р.memory && р.phone, Object.keys(р).join(' '));
  проверить('память: секреты с полями', р.memory.secrets[0].fact === 'тайна' && р.memory.secrets[0].level === 'high', JSON.stringify(р.memory));
  проверить('телефон: контакты', р.phone.contacts[0].name === 'Марк', JSON.stringify(р.phone));
  const назад = C.свернутьКоды(JSON.parse(JSON.stringify(р)));
  проверить('свернуть обратно — те же коды корня', назад.sc && назад.cs && назад.me && назад.phn, Object.keys(назад).join(' '));
}

// ---------------------------------------------------------------------------
группа('names: сравнение имён');
{
  проверить('кириллица и латиница', N.namesLikelySame('Тристан', 'Tristan'));
  проверить('имя и полное имя', N.namesLikelySame('Tristan', 'Tristan Kingsley'));
  проверить('регистр и ё', N.namesLikelySame('Алёна', 'алена'));
  проверить('разные люди — не одно', !N.namesLikelySame('Марк', 'Мария'));
  проверить('пустое не совпадает ни с чем', !N.namesLikelySame('', 'Марк'));
  равно('транслитерация', N.transliterateCyrillic('Софи').toLowerCase(), 'sofi');
  // Инициалы: прозвище в кавычках — не часть имени, инициал — имя и фамилия.
  const И = (x, n) => U.инициалыИмени(x, n);
  проверить('отношения: «Долорес «Лола» Ховард: тётя» — подпись целиком и кружок ДХ', /hud-pill-face[^>]*>ДХ/.test(U.buildPillList('Долорес «Лола» Ховард: тётя; Тристан: муж', 'hud-detail-pill', false, 'отношения')));
  равно('инициалы: прозвище в кавычках любых видов', [И('Долорес "Лола" Ховард'), И('Долорес «Лола» Ховард'), И('Долорес “Лола” Ховард'), И('"Лола" Ховард'), И('Evangeline Rose Kane'), И("Sean O'Neil"), И('THE REGENTS  Tristan Kingsley'), И('Долорес "Лола" Ховард', 1)].join(' '), 'ДХ ДХ ДХ Х EK SO TK Д');
  // Короткие имена: одна буква — другое имя; транслит и падеж — то же самое.
  const одно = [['Мия', 'Mia'], ['Лея', 'Leia'], ['Кейт', 'Kate'], ['Зои', 'Zoe'], ['Ной', 'Noah'], ['Ария', 'Aria'], ['Джейн', 'Jane'], ['Грейс', 'Grace'],
    ['Тристану', 'Tristan'], ['Коэном', 'Koen'], ['Аресом', 'Ares'], ['Эванджелиной', 'Evangeline'], ['Изольда', 'Isolde'], ['Готье', 'Gauthier'], ['Ксавьер', 'Xavier'], ['Кристина', 'Christina']];
  const разные = [['Мия', 'Лея'], ['Мия', 'Мая'], ['Ева', 'Ана'], ['Лея', 'Лия'], ['Анна', 'Инна'], ['Ария', 'Мария'], ['Мария', 'Дария'], ['Лиза', 'Лина'], ['Leo', 'Lea'],
    ['Тристан', 'Кристина'], ['Шеф', 'Sophie'], ['Кофе', 'Koen'], ['Он', 'Koen'], ['Грея', 'Grace'], ['Греть', 'Grace'], ['Гейт', 'Gauthier'], ['Кейн', 'Коэн'], ['София', 'Софи'], ['Софию', 'Sophie'], ['Софии', 'Sophie'], ['Sophia', 'Sophie'], ['Зоя', 'Зои']];
  const мимо = [...одно.filter(([a, b]) => !N.namesLikelySame(a, b)).map(p => '≠ ' + p), ...разные.filter(([a, b]) => N.namesLikelySame(a, b)).map(p => '= ' + p)];
  проверить('имена: короткие разные не сливаются, транслит и падежи узнаются', !мимо.length, мимо.join(' | '));
  // Списки под картинкой: «Эва, Эванджелина, Ева» — один человек, и в тексте тоже.
  const { settings: НСи } = await модуль('settings.js');
  const былоИмён = НСи.avatarCharNames;
  НСи.avatarCharNames = 'Эва, Эванджелина, Ева, Evangeline Rose Kane';
  проверить('имена из списка картинки: «Эва» — Эванджелина, и в тексте «Эва приняла душ»', N.namesLikelySame('Эва', 'Evangeline Rose Kane') && N.упомянутВТексте('Утром Эва приняла душ.', 'Evangeline Rose Kane') && !N.упомянутВТексте('Утром Лея приняла душ.', 'Evangeline Rose Kane'));
  НСи.avatarCharNames = 'Софи, София, Sophie Howard';
  проверить('список картинки «Софи, София»: «Софию» и «Софией» — тот же человек', N.namesLikelySame('Софию', 'Sophie Howard') && N.упомянутВТексте('рядом с Софией', 'Sophie Howard'));
  НСи.avatarCharNames = былоИмён;
  проверить('без списка «Софию» — не Софи', !N.namesLikelySame('Софию', 'Sophie Howard'));
  проверить('упомянут в тексте: падеж и транслит без списков', !N.упомянутВТексте('Тристан смотрел в окно', 'Sophie Howard') && !N.упомянутВТексте('Тристан смотрел на Софию', 'Sophie Howard') && N.упомянутВТексте('Тристан смотрел на Софи', 'Sophie Howard') && N.упомянутВТексте('рядом с Эванджелиной', 'Evangeline Kane'));
}

// ---------------------------------------------------------------------------
группа('вкладки: порядок, скрытие, закрепление');
{
  const TO = await модуль('tabs-order.js');
  const в = ['character', 'character', 'user', 'phone', 'memory', 'life', 'world'].map((id, i) => ({ id, n: i }));
  const ids = (s) => TO.упорядочитьВкладки(в, s).map(т => т.id + т.n).join(' ');
  равно('без настроек — как собрал renderHUD', ids({}), 'character0 character1 user2 phone3 memory4 life5 world6');
  равно('tabOrder: группа персонажей переставляется целиком, люди — по порядку появления', ids({ tabOrder: ['life', 'character'] }), 'life5 character0 character1 user2 phone3 memory4 world6');
  равно('закреплённые — первыми', ids({ tabOrder: ['life', 'character'], tabPinned: ['world'] }), 'world6 life5 character0 character1 user2 phone3 memory4');
  равно('скрытые не показываются', ids({ tabHidden: ['phone', 'memory'] }), 'character0 character1 user2 life5 world6');
  равно('скрыто всё — показываем всё, а не пустую карточку', ids({ tabHidden: ['character', 'user', 'phone', 'memory', 'life', 'world'] }), 'character0 character1 user2 phone3 memory4 life5 world6');
  равно('незнакомые id в настройках не мешают', ids({ tabOrder: ['nope', 'memory'] }), 'memory4 character0 character1 user2 phone3 life5 world6');
  const полный = TO.полныйПорядок({ tabOrder: ['life', 'старый'] });
  проверить('полный порядок: сохранённое первым, незнакомое не теряется, остальные — из списка', полный[0] === 'life' && полный[1] === 'старый' && полный.includes('world') && полный.length === TO.ВКЛАДКИ.length + 1);
  равно('сдвинуть вверх', TO.сдвинуть(['a', 'b', 'c'], 'c', -1).join(), 'a,c,b');
  равно('сдвинуть за край — без изменений', TO.сдвинуть(['a', 'b', 'c'], 'a', -1).join(), 'a,b,c');
}

// ---------------------------------------------------------------------------
группа('бюджет токенов и усиления');
{
  const TB = await модуль('token-budget.js');
  const AP = await модуль('adapt-prompt.js');
  const { settings: Sb } = await модуль('settings.js');
  const было = { enablePhone: Sb.enablePhone, enableWorld: Sb.enableWorld };
  Sb.enablePhone = true; Sb.enableWorld = true;
  const собрать = ({ nsfw, бой }) => 'base rules '.repeat(50) + (Sb.enablePhone !== false ? 'phone '.repeat(80) : '') + (Sb.enableWorld ? 'мир '.repeat(40) : '') + (nsfw ? 'nsfw '.repeat(30) : '') + (бой ? 'бой '.repeat(10) : '');
  const б = TB.бюджетИнструкции(собрать, { nsfw: false, бой: false });
  const тел = б.разделы.find(р => р.имя === 'Телефон'), близ = б.разделы.find(р => р.имя === 'Близость');
  проверить('бюджет: разделы по цене, телефон дороже мира, основа — остаток', б.разделы[0].имя === 'Телефон' && тел.цена > б.разделы.find(р => р.имя === 'Мир').цена && б.основа > 0 && б.основа < б.всего, JSON.stringify(б.разделы.slice(0, 4)));
  проверить('бюджет: близость вне сцены — с пометкой «только в сцене» и не в сумме', близ && близ.когда === 'только в сцене' && близ.цена > 0);
  проверить('бюджет: настройки после замеров те же (finally)', Sb.enablePhone === true && Sb.enableWorld === true);
  проверить('бюджет: выключенный блок не меряется', (Sb.enablePhone = false, !TB.бюджетИнструкции(собрать, {}).разделы.some(р => р.имя === 'Телефон')));
  Object.assign(Sb, было);
  проверить('оценка: кириллица дороже латиницы на знак', TB.оценкаТокенов('аааааааааа') > TB.оценкаТокенов('aaaaaaaaaa'));
  равно('коротко: 4100 → 4,1k', TB.коротко(4100), '4,1k');
  const панель = TB.разметкаБюджета({ запрос: 3000, инструкция: б, снимок: 900, ответ: 700, сейф: 0, усиление: 18, слабые: [{ имя: 'мысли' }] });
  проверить('панель: строки разделов, «выключить», усиления и основа', /hud-budget-off" data-key="enablePhone"/.test(панель) && /Усиления/.test(панель) && /Основа/.test(панель) && /data-key="nsfwPrompt" data-value="&quot;never&quot;"/.test(панель));

  // Усиления: на модель, минимум наблюдений, потолок, забывание, выключенное не усиливаем.
  const мета = {};
  const ход = (th) => hud({ sc: { Dt: '01.06.2028', T: '10:00' }, cs: [{ N: 'Лея', Th: th ? 'думает' : 'empty', Ex: 'ждала — получила' }], wd: { zd: 'Овен: день' }, dy: [{ au: 'Лея', tx: 'Сегодня было долго и тихо.' }] });
  for (let i = 0; i < 11; i++) AP.учестьОтвет(мета, 'A', AP.наблюденияПолей(ход(false)));
  проверить('усиления: 11 ходов — мало, молчим', AP.строкаУсиления(мета, 'A') === '');
  AP.учестьОтвет(мета, 'A', AP.наблюденияПолей(ход(false)));
  проверить('усиления: 12 ходов без мыслей — строка про Th', /Th \(thoughts\)/.test(AP.строкаУсиления(мета, 'A')) && !/Ex/.test(AP.строкаУсиления(мета, 'A')));
  проверить('усиления: у другой модели свой счёт', AP.строкаУсиления(мета, 'B') === '');
  for (let i = 0; i < 50; i++) AP.учестьОтвет(мета, 'A', AP.наблюденияПолей(ход(true)));
  проверить('усиления: модель исправилась — окно 50 ходов забыло старое', AP.строкаУсиления(мета, 'A') === '' && мета.tavernosHudFieldStats.A.Th.length === 50);
  const выкл = Sb.hudAdaptPrompt; Sb.hudAdaptPrompt = false;
  for (let i = 0; i < 20; i++) AP.учестьОтвет(мета, 'C', AP.наблюденияПолей(ход(false)));
  проверить('усиления: выключены настройкой — строки нет', AP.строкаУсиления(мета, 'C') === '');
  Sb.hudAdaptPrompt = выкл;
}

// ---------------------------------------------------------------------------
группа('дуэль → секреты: слой правок снимка');
{
  const SE = await модуль('snapshot-edits.js');
  const SG = await модуль('render/secrets-grid.js');
  const HS = await модуль('hud-snapshot.js');
  const { settings: Sx } = await модуль('settings.js');
  const м = {};
  const былСТ = globalThis.SillyTavern;
  globalThis.SillyTavern = { getContext: () => ({ chat: [], chatMetadata: м }) };
  const факт = 'Софи знала о помолвке Тристана с Викторией заранее';
  равно('ключ секрета не зависит от хвоста фразы', SE.ключСекрета(факт), SE.ключСекрета('Софи знала о помолвке Тристана с Викторией'));
  const секреты = [
    { fact: факт, level: 'critical', status: 'unknown', knows: [{ name: 'Софи', source: 'сама' }], hidden: ['Лена', 'Тристан'] },
    { fact: 'У Ареса долг казино в Монако', level: 'high', knows: [{ name: 'Арес' }], hidden: [] },
    { fact: 'Лена тайно встречается с Коэном', level: 'medium', knows: [{ name: 'Лена' }], hidden: [] },
  ];
  const ход = { characters: [
    { 'Имя': 'Тристан', 'Словесная дуэль': 'ini: Тристан, 60; gv: Софи призналась, что знала о помолвке с Викторией; tn: ссора', 'Глубина конфликта': 'wy: помолвка с Викторией; dys: 2' },
    { 'Имя': 'Лена' },
  ] };
  const предл = SE.всплывшиеСекреты(секреты, [{ уступка: 'Софи призналась, что знала о помолвке с Викторией', суть: '' }], ['Софи', 'Тристан', 'Лена'], SG.клеткаСекрета);
  проверить('всплыло: уступка в дуэли — «знает» для Тристана и Лены, Софи уже знает', предл.length === 2 && предл.every(п => п.значение === 'known') && !предл.some(п => п.кто === 'Софи'), JSON.stringify(предл.map(п => [п.кто, п.значение])));
  проверить('всплыло: только суть спора — «подозревает»', SE.всплывшиеСекреты(секреты, [{ уступка: '', суть: 'помолвка Тристана с Викторией' }], ['Лена'], SG.клеткаСекрета)[0]?.значение === 'suspected');
  проверить('всплыло: одно общее слово — не совпадение', !SE.совпадаетССекретом('помолвка', факт));
  const былаСетка = Sx.secretsGrid; Sx.secretsGrid = 'on';
  const сетка = SG.сеткаСекретов(секреты, ход);
  проверить('сетка: предложение «отметить знает» с кнопками, клетка подсвечена', /hud-sgrid-raise/.test(сетка) && /data-value="known"/.test(сетка) && /data-value="dismissed"/.test(сетка) && /is-proposed/.test(сетка));
  SE.правитьСнимок(SE.путьСекрета(факт, 'Лена'), 'known', 299);
  const сетка2 = SG.сеткаСекретов(секреты, ход);
  проверить('после «отметить»: у Лены правка и расхождение (модель пишет «не знает»), снова не спрашивает про Лену', /has-edit/.test(сетка2) && /is-conflict/.test(сетка2) && !/при Лена/.test(сетка2) && /data-sec-edit="sec\|[^"]*\|Лена" data-value=""/.test(сетка2));
  SE.правитьСнимок(SE.путьСекрета(факт, 'Тристан'), 'dismissed');
  const сетка3 = SG.сеткаСекретов(секреты, ход);
  проверить('«нет» — больше не спрашивает про Тристана', !/при Тристан/.test(сетка3), (сетка3.match(/<em>при [^<]*/g) || []).join(' | '));
  const снимок = { me: { sec: [{ f: факт, lv: 'critical', knw: [{ n: 'Софи', src: 'сама' }], hd: ['Лена', 'Тристан'] }] } };
  const строка = HS.строкаСнимка(снимок, false);
  проверить('снимок модели: Лена — в knw с пометкой игрока и не в hd; Тристан («нет») не тронут; исходный объект цел', /"n":"Лена","src":"узнал\(а\) — отметил игрок"/.test(строка) && /"hd":\["Тристан"\]/.test(строка) && снимок.me.sec[0].hd.length === 2, строка.slice(0, 400));
  проверить('снять правку', SE.снятьПравку(SE.путьСекрета(факт, 'Лена')) && !SE.правкаСекрета(факт, 'Лена'));
  Sx.secretsGrid = былаСетка;
  globalThis.SillyTavern = былСТ;
}

