группа('hud-block: маска рассуждений');
{
  const блок = hud({ sc: { T: '10:00' }, cs: [{ N: 'Лилиан' }] });
  const вПлане = '<plan>Не забыть [HUD]...[/HUD] в конце</plan>\nОтвет.';
  проверить('HUD только в <plan> — блока нет', !B.естьHudБлок(вПлане) && !B.extractHudBlock(вПлане) && B.hudБлоки(вПлане).length === 0);
  const оба = '<think>черновик [HUD]{"x":1}[/HUD]</think>\nТекст.\n' + блок;
  проверить('из двух берётся настоящий, вне рассуждений', B.hudБлоки(оба).length === 1 && /Лилиан/.test(B.extractHudBlock(оба)));
  const маска = B.маскаРассуждений(оба);
  проверить('маска той же длины', маска.length === оба.length);
  const заменено = B.заменитьHudБлоки(оба, '');
  проверить('замена не трогает рассуждения', заменено.includes('<think>черновик [HUD]') && !заменено.includes('Лилиан'), заменено.slice(0, 200));
  const незакрытый = '<plan>план без закрытия\n' + блок;
  проверить('незакрытое рассуждение не прячет настоящий HUD с данными', B.естьHudБлок(незакрытый));
  проверить('последний блок — позиция и длина', (() => { const п = B.последнийHudБлок('А\n' + блок); return п && п.index === 2 && п.length === блок.length; })());
}

