группа('карточка: без сознания, цикл сейчас');
{
  const Ch = await модуль('render/character.js');
  const I = await модуль('render/intimacy.js');
  const б = (поля) => Ch.безСознания(поля);
  проверить('«потеряла сознание» — плашка', /потеряла сознание/.test(б({ 'Тело': 'бледная, потеряла сознание от удара' })));
  проверить('«в обмороке» в здоровье', !!б({ 'Здоровье': 'в обмороке' }));
  проверить('«отключилась» — да, «отключила телефон» — нет', !!б({ 'Тело': 'отключилась прямо на диване' }) && !б({ 'Тело': 'отключила телефон' }));
  проверить('отрицание «чуть не отключилась» — нет', !б({ 'Тело': 'чуть не отключилась от боли' }));
  проверить('«едва не потеряла сознание» — нет', !б({ 'Физиология': 'едва не потеряла сознание' }));
  проверить('«очнулась» снимает плашку', !б({ 'Тело': 'была без сознания, очнулась на полу' }));
  проверить('обычное состояние — нет', !б({ 'Тело': 'устала, но держится' }));
  проверить('«решимость после обморока» — нет (чат THE REGENTS)', !б({ 'Тело': 'отчаянная решимость после обморока' }));
  проверить('«после того как потеряла сознание» — нет', !б({ 'Тело': 'слабость после того как потеряла сознание' }));
  проверить('«упала в обморок» — да', !!б({ 'Тело': 'упала в обморок на кухне' }));
  проверить('невидимые пробелы U+2800 не мешают отрицанию', !б({ 'Тело': 'чуть⠀не⠀отключилась' }));
  {
    const фаза1 = Ch.buildCharacterHTML({ 'Имя': 'Эванджелин', 'Фаза близости': '1 — empty', 'Жизненные показатели': 'hr: 118; br: 22', 'Карта тела': 'Пальцы: 5 rising — ледяные', 'Тело': 'дрожит' }, 'f1', true, true);
    проверить('фаза 1: пульс и карта тела в карточку не выводятся', !/Жизненные показатели|Карта тела/.test(фаза1) && /дрожит/i.test(фаза1));
    const фаза2 = Ch.buildCharacterHTML({ 'Имя': 'Эванджелин', 'Фаза близости': '2 — act', 'Жизненные показатели': 'hr: 118; br: 22' }, 'f2', true, true);
    проверить('фаза 2: пульс выводится', /hud-vit|118/.test(фаза2));
  }

  const ц = I.циклСейчас('cyd: 14; cyl: 28; phs: ovulation');
  проверить('цикл: овуляция на 14-й день', ц && ц.фаза === 'ovulation' && ц.день === 14 && ц.ov === 14, JSON.stringify(ц));
  проверить('цикл: фаза по дню, если модель её не назвала', I.циклСейчас('cyd: 3; cyl: 30').фаза === 'menstrual');
  проверить('цикл: задержка', I.циклСейчас('cyd: 33; cyl: 28; dly: 5').опоздание === true);
  проверить('цикл: ПМС в конце лютеиновой', I.циклСейчас('cyd: 25; cyl: 28; phs: luteal').пмс === true);
  проверить('цикл: пусто — нет', I.циклСейчас('empty') === null);
  проверить('модификаторы овуляции: либидо и шанс', I.модификаторыФазы(ц).length === 2);
  const р = I.рискЗачатия(14, 28, 'ovulation', { ov: 14, защита: 'condom: надели' });
  проверить('риск: презерватив снижает шанс', р.шанс < I.рискЗачатия(14, 28, 'ovulation', { ov: 14 }).шанс);

  // Весь пример целиком через сборщики карточек — ловит ReferenceError в
  // ветках, которые срабатывают только на полном наборе полей.
  const S = await модуль('render/sample-hud.js');
  const д = Sch.normalizeJSONData(P.parseHUDComplex(S.ПРИМЕР_HUD_ТЕКСТ.split('{{user}}').join('Софи')));
  const люди = [...д.characters.map(c => ({ имя: c['Имя'], данные: c })), { имя: 'Софи', данные: д.user }];
  люди.forEach(п => Object.defineProperty(п.данные, '__соседи', { value: люди, configurable: true }));
  let карточки = '', ошибка = '';
  try {
    карточки = д.characters.map((c, i) => Ch.buildCharacterHTML(c, 'u' + i, false, i === 0)).join('') + Ch.buildUserHTML(д.user, 'uu', false, д.characters);
  } catch (e) { ошибка = e.stack || String(e); }
  проверить('полный пример собирается без ошибок', !ошибка, ошибка);
  проверить('модификаторы сцены в примере есть', карточки.includes('hud-scene-mods'));
  проверить('шанс зачатия у партнёра по сцене', карточки.includes('is-partner'));
}

